create table if not exists employee_account (id bigint not null auto_increment comment 'account primary key', employee_id bigint not null comment 'employee id', login_phone varchar(32) comment 'login phone', password_hash varchar(255) comment 'password hash', status varchar(32) not null default 'ACTIVE' comment 'status', primary key(id), unique key uk_account_employee(employee_id)) engine=InnoDB default charset=utf8mb4 comment='employee account';
create table if not exists auth_session (id bigint not null auto_increment comment 'session primary key', employee_account_id bigint not null comment 'account id', access_token_hash varchar(128) not null comment 'access token hash', refresh_token_hash varchar(128) not null comment 'refresh token hash', access_expires_at datetime(3) not null comment 'access expiry', refresh_expires_at datetime(3) not null comment 'refresh expiry', revoked_at datetime(3) comment 'revoked time', primary key(id), unique key uk_access_hash(access_token_hash)) engine=InnoDB default charset=utf8mb4 comment='auth session';

